// Regression checks for the operational/OOS display boundary.
// In this repo the operational export is regenerated by qsignals.export_frontend on
// every refresh, so these checks test the rules against whatever export is present
// instead of pinning one run's numbers.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const source = fs.readFileSync('src/lib/operational-status.ts', 'utf8');
const code = ts.transpileModule(source, {compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText;
const moduleValue = {exports:{}};
vm.runInNewContext(code, {module:moduleValue,exports:moduleValue.exports});
const {currentOperationalPoint, lastValidOperationalPoint, operationalMessage} = moduleValue.exports;
const data = JSON.parse(fs.readFileSync('public/data/operational-markets.json', 'utf8'));
assert.equal(data.schema_version, 1);
assert.equal(data.sourceValuesIncluded, false);
for (const [name, market] of Object.entries(data.markets)) {
 const current = currentOperationalPoint(market);
 if (market.status === 'CURRENT') {
  assert.equal(current.date, market.expectedDate, `${name}: current score must be for the expected date`);
  assert.equal(lastValidOperationalPoint(market), null, `${name}: no last-valid fallback when current exists`);
  assert.ok(operationalMessage(market, 'en').includes('verified'));
 } else {
  assert.equal(current, null, `${name}: no current score unless CURRENT`);
  if (market.lastValid) assert.equal(lastValidOperationalPoint(market).date, market.lastValid.date);
  assert.ok(!/[가-힣]/.test(operationalMessage(market, 'en')));
 }
 for (const point of market.history) {
  assert.equal(point.price, null, `${name}: operational export must not carry prices`);
  assert.ok(point.risk >= 0 && point.risk <= 1, `${name} ${point.date}: risk outside 0-1`);
 }
 // A past record is never promoted to current.
 if (market.lastValid) assert.equal(currentOperationalPoint({...market, status:'CURRENT', current:market.lastValid, expectedDate:'2999-01-01'}), null);
}
// Value gates on a synthetic CURRENT market.
const point = {date:'2026-11-09', price:null, risk:0.4, msi:1, threshold:1.1, recordType:'OPERATIONAL'};
const ok = {status:'CURRENT', expectedDate:'2026-11-09', current:point, lastValid:point, history:[point], reason:null};
assert.equal(currentOperationalPoint(ok).date, '2026-11-09');
assert.equal(currentOperationalPoint({...ok, current:{...point, date:'2026-11-08'}}), null);
for (const risk of [NaN, Infinity, -0.1, 1.1, null]) assert.equal(currentOperationalPoint({...ok, current:{...point, risk}}), null);
assert.equal(currentOperationalPoint({...ok, current:{...point, msi:null}}), null);
assert.equal(currentOperationalPoint({...ok, current:null}), null);
assert.equal(currentOperationalPoint(null), null);
assert.equal(lastValidOperationalPoint({...ok, status:'DELAYED', current:null, lastValid:{...point, risk:1.1}}), null);
assert.ok(operationalMessage({...ok, status:'BLOCKED', current:null, reason:null}, 'en').includes('withheld'));
assert.ok(operationalMessage(null, 'en').includes('No operational export'));
// Frozen research exports keep their walk-forward OOS end dates.
const historical = JSON.parse(fs.readFileSync('public/data/global-markets.json', 'utf8'));
assert.equal(historical.korea.filter(p=>p.risk!==null).at(-1).date,'2026-09-16');
assert.equal(historical.us.filter(p=>p.risk!==null).at(-1).date,'2026-09-21');
console.log('PASS: current/last-valid separation per market, no prices, value gates, bilingual status and preserved OOS dates');
